char*recite(unsigned a,unsigned b){const char*things[]={"the house that Jack built.","the malt","the rat","the cat","the dog","the cow with the crumpled horn","the maiden all forlorn","the man all tattered and torn","the priest all shaven and shorn","the rooster that crowed in the morn","the farmer sowing his corn","the horse and the hound and the horn"};const char*verbs[]={"lay in","ate","killed","worried","tossed","milked","kissed","married","woke","kept","belonged to"};char*out=(char*)calloc(16000,1);if(a<1||b>12||a>b)return out;for(unsigned i=a;i<=b;i++){if(i>a)strcat(out,"\n");strcat(out,"This is ");strcat(out,things[i-1]);for(int j=(int)i-2;j>=0;j--){strcat(out," that ");strcat(out,verbs[j]);strcat(out," ");strcat(out,things[j]);}}return out;}

